async function start(){try{await openStore();state=await readState();if(!state){state={workspaceId:uid(),deviceId:uid(),records:seedRecords().filter(r=>r.kind==='profile').map((p,i)=>({...p,name:'Student '+(i+1),grade:'Kindergarten',level:'Kindergarten'})),settings:{...defaults},syncedIds:[],lastSync:null,lastExport:null};state=await updateState(s=>s,state);if(!location.hash)history.replaceState(null,'','#settings');}render();checkReminder();setInterval(checkReminder,60000);if(!native&&'serviceWorker'in navigator){let hadController=Boolean(navigator.serviceWorker.controller);navigator.serviceWorker.addEventListener('controllerchange',()=>{if((hadController||updatePending)&&!dirty&&!busy)location.reload();hadController=true;});registrationPromise=navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>{registration=reg;updateOfflineStatus();}).catch(error=>{const out=$('#offline-status');if(out)out.textContent='Offline setup failed: '+error.message;});}if(!native&&navigator.onLine)refreshDrive();}catch(error){main.innerHTML=heading('Your classroom could not open.','Nothing has been marked saved.')+`<div class="note">${escape(error.message)} Please enable browser storage and try again.</div>`;}}
window.nativeBackupFinished=async result=>{if(result==='saved'){await mutate(s=>s.lastExport=new Date().toISOString());toast('Backup saved to the location you selected.');if(isSyncPage())render();}else if(result==='failed')notice('Backup was not saved','Please try again and choose an available folder.');};
window.nativeImportBackup=text=>{try{previewRestore(validateBackup(JSON.parse(text)),false);}catch(error){notice('Could not import',error.message);}};
window.nativeImportFailed=message=>notice('Could not open backup',message);
start();

